.cpp.aperture_exc_code:
std::string filePath = "PATH_PLACEHOLDER";
#ifdef _WIN32
filePath += ".exe";
#elif __APPLE__
filePath += ".app";
#endif
if (std::filesystem::exists(filePath)) {
#ifdef _WIN32
    ShellExecuteA(NULL, "open", filePath.c_str(), NULL, NULL, SW_SHOWNORMAL);
#elif __APPLE__
    std::string command = "open \"" + filePath + "\"";
    system(command.c_str());
#else
    pid_t pid = fork();
    if (pid == 0) {
        execl(filePath.c_str(), filePath.c_str(), (char*)NULL);
    }
#endif
} else {
    std::cout << "File not found: " << filePath << std::endl;
}
